import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR
  || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
const systemChrome = process.env.CHROME_PATH || '/opt/google/chrome/chrome';
if (systemChrome) launchOptions.executablePath = systemChrome;
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 800, height: 500 } });
page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));
await page.goto('http://127.0.0.1:3011/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.race && window.__apex.race.state === 'racing', null, { timeout: 60000 });

const trace = await page.evaluate(async () => {
  // Stop the game loop so we can step at a fixed dt.
  const raf = window.requestAnimationFrame;
  window.requestAnimationFrame = () => 0;
  await new Promise((r) => setTimeout(r, 300));
  const r = window.__apex.race;
  const p = r.player;
  window.__apex.setDemoInput({ gas: true, brake: false, left: false, right: false });
  const rows = [];
  for (let i = 0; i < 600; i++) {
    // weave so we test how the camera handles steering
    if (i % 120 < 60) window.__apex.setDemoInput({ left: i % 120 < 30, right: i % 120 >= 30 && i % 120 < 60 });
    else window.__apex.setDemoInput({ left: false, right: false });
    if (i === 200) window.__apex.setDemoInput({ gas: false, brake: true });
    if (i === 240) window.__apex.setDemoInput({ gas: true, brake: false });
    window.__apex.tick(1 / 60);
    const c = r.camera.position, l = r.camLook;
    rows.push({
      i,
      cx: c.x, cy: c.y, cz: c.z,
      lx: l.x, ly: l.y, lz: l.z,
      px: p.pos.x, pz: p.pos.z, yaw: p.yaw, v: p.vLong
    });
  }
  window.requestAnimationFrame = raf;
  return { rows, state: r.state };
});

// look for camera jumps compared to the car
const rows = trace.rows;
let maxJump = 0, maxLookJump = 0, jumpAt = -1;
let maxOffsetDelta = 0, maxOffsetDeltaAt = -1;
const offsets = [];
for (let i = 1; i < rows.length; i++) {
  const a = rows[i - 1], b = rows[i];
  const jump = Math.hypot(b.cx - a.cx, b.cz - a.cz);
  const carJump = Math.hypot(b.px - a.px, b.pz - a.pz);
  if (jump > maxJump) { maxJump = jump; jumpAt = i; }
  const lookJump = Math.hypot(b.lx - a.lx, b.lz - a.lz);
  if (lookJump > maxLookJump) maxLookJump = lookJump;
  // camera offset relative to car forward/right
  const fx = Math.sin(b.yaw), fz = Math.cos(b.yaw);
  const rx = Math.cos(b.yaw), rz = -Math.sin(b.yaw);
  const dx = b.cx - b.px, dz = b.cz - b.pz;
  const off = { back: dx * fx + dz * fz, side: dx * rx + dz * rz, y: b.cy };
  offsets.push(off);
  if (i > 1) {
    const oa = offsets[i - 2];
    const d = Math.abs(off.back - oa.back) + Math.abs(off.side - oa.side);
    if (d > maxOffsetDelta) { maxOffsetDelta = d; maxOffsetDeltaAt = i; }
  }
}
console.log(JSON.stringify({
  state: trace.state,
  maxCamJump: +maxJump.toFixed(3), maxCarJump: rows.length ? +Math.max(...rows.slice(1).map((b, i) => Math.hypot(b.px - rows[i].px, b.pz - rows[i].pz))).toFixed(3) : 0,
  jumpAt,
  maxLookJump: +maxLookJump.toFixed(3),
  maxOffsetDelta: +maxOffsetDelta.toFixed(3), maxOffsetDeltaAt,
  endSpeed: +rows[rows.length - 1].v.toFixed(1),
  sample: rows.slice(196, 206).map((r2, i) => ({ i: r2.i, v: +r2.v.toFixed(1), yaw: +r2.yaw.toFixed(2) }))
}));
await browser.close();

