import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR
  || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
launchOptions.executablePath = process.env.CHROME_PATH || '/opt/google/chrome/chrome';
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 800, height: 500 } });
page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));
await page.goto('http://127.0.0.1:3011/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.race && window.__apex.race.state === 'racing', null, { timeout: 60000 });

const trace = await page.evaluate(async () => {
  const raf = window.requestAnimationFrame;
  window.requestAnimationFrame = () => 0;
  await new Promise((res) => setTimeout(res, 250));
  const r = window.__apex.race;
  const p = r.player;
  const tr = r.track;
  const N = tr.N;
  const wrap = (a) => { while (a > Math.PI) a -= Math.PI * 2; while (a < -Math.PI) a += Math.PI * 2; return a; };
  const rows = [];
  for (let i = 0; i < 1400; i++) {
    // simple auto-steer so the car stays on the circuit for the whole run
    const ahead = tr.samples[(((p.sNorm * N) | 0) + Math.round(22 / tr.step) + N) % N];
    const err = wrap(Math.atan2(ahead.x - p.pos.x, ahead.z - p.pos.z) - p.yaw);
    window.__apex.setDemoInput({ gas: false, brake: false, left: err > 0.02, right: err < -0.02 });
    window.__apex.tick(1 / 60);
    const c = r.camera.position;
    rows.push({
      i,
      cx: c.x, cy: c.y, cz: c.z,
      px: p.pos.x, pz: p.pos.z,
      yaw: p.yaw, camYaw: r.camYaw,
      v: p.vLong, off: p.offroad ? 1 : 0
    });
  }
  window.requestAnimationFrame = raf;
  return rows;
});

let maxCarJump = 0;
let maxCamJump = 0;
let maxOffsetStep = 0;
let maxOffsetAcc = 0;
let maxCamYawStep = 0;
const worst = [];
for (let i = 2; i < trace.length; i++) {
  const a = trace[i - 2], b = trace[i - 1], c = trace[i];
  const carJump = Math.hypot(c.px - b.px, c.pz - b.pz);
  const camJump = Math.hypot(c.cx - b.cx, c.cz - b.cz);
  maxCarJump = Math.max(maxCarJump, carJump);
  maxCamJump = Math.max(maxCamJump, camJump);
  maxCamYawStep = Math.max(maxCamYawStep, Math.abs(c.camYaw - b.camYaw));
  const fx = Math.sin(c.yaw), fz = Math.cos(c.yaw);
  const rx = Math.cos(c.yaw), rz = -Math.sin(c.yaw);
  const off = (q) => ({ back: (q.cx - q.px) * fx + (q.cz - q.pz) * fz, side: (q.cx - q.px) * rx + (q.cz - q.pz) * rz });
  const oa = off(a), ob = off(b), oc = off(c);
  const step = Math.abs(oc.back - ob.back) + Math.abs(oc.side - ob.side);
  const acc = Math.abs(oc.back - 2 * ob.back + oa.back) + Math.abs(oc.side - 2 * ob.side + oa.side);
  maxOffsetStep = Math.max(maxOffsetStep, step);
  if (acc > maxOffsetAcc) { maxOffsetAcc = acc; worst.push({ i: c.i, acc: +acc.toFixed(3), v: +c.v.toFixed(1), back: +oc.back.toFixed(2), side: +oc.side.toFixed(2), camYaw: +c.camYaw.toFixed(2), yaw: +c.yaw.toFixed(2) }); }
}
console.log(JSON.stringify({
  frames: trace.length,
  maxCarJump: +maxCarJump.toFixed(2),
  maxCamJump: +maxCamJump.toFixed(2),
  maxCamYawStep: +maxCamYawStep.toFixed(3),
  maxOffsetStep: +maxOffsetStep.toFixed(3),
  maxOffsetAcc: +maxOffsetAcc.toFixed(3),
  worst: worst.slice(-4),
  speedMax: +Math.max(...trace.map((r) => r.v)).toFixed(1),
  offroadFrames: trace.filter((r) => r.off).length
}, null, 1));
await browser.close();

