import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR
  || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
launchOptions.executablePath = process.env.CHROME_PATH || '/opt/google/chrome/chrome';
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:3011/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.race && window.__apex.race.state === 'racing', null, { timeout: 60000 });
await page.waitForTimeout(800);

const out = await page.evaluate(async () => {
  const { audio } = await import('/src/audio.js');
  const ctx = audio.ensure();
  // Tap the race bus so we can inspect the actual spectrum.
  const analyser = ctx.createAnalyser();
  analyser.fftSize = 8192;
  analyser.smoothingTimeConstant = 0.2;
  audio.raceBus.connect(analyser);

  const snap = () => ({
    ctxState: ctx.state,
    gear: audio.lastGear,
    oscA: +audio.oscA.frequency.value.toFixed(1),
    oscB: +audio.oscB.frequency.value.toFixed(1),
    oscD: +audio.oscD.frequency.value.toFixed(1),
    filter: +audio.engineFilter.frequency.value.toFixed(0),
    turbo: +audio.turboOsc.frequency.value.toFixed(0),
    engineLevel: +audio.engineGain.gain.value.toFixed(4),
    tyre: +audio.tyreGain.gain.value.toFixed(4)
  });

  const r = window.__apex.race;
  const p = r.player;
  const setSpeed = (ms) => {
    p.vLong = ms;
    p.vel.x = Math.sin(p.yaw) * ms;
    p.vel.z = Math.cos(p.yaw) * ms;
  };

  const states = [];
  for (const ms of [0, 15, 40, 70, 90]) {
    setSpeed(ms);
    for (let i = 0; i < 90; i++) window.__apex.tick(1 / 60);
    await new Promise((res) => setTimeout(res, 160));
    states.push({ ms, ...snap() });
  }

  // spectrum at the last (high speed) state
  setSpeed(90);
  for (let i = 0; i < 90; i++) window.__apex.tick(1 / 60);
  await new Promise((res) => setTimeout(res, 250));
  const data = new Float32Array(analyser.frequencyBinCount);
  analyser.getFloatFrequencyData(data);
  const binHz = ctx.sampleRate / analyser.fftSize;
  const peaks = [];
  for (let i = 2; i < data.length - 1; i++) {
    if (data[i] > data[i - 1] && data[i] > data[i + 1] && data[i] > -70) {
      peaks.push({ hz: Math.round(i * binHz), db: +data[i].toFixed(1) });
    }
  }
  peaks.sort((a, b) => b.db - a.db);
  return { states, topPeaks: peaks.slice(0, 14) };
});
console.log(JSON.stringify(out, null, 1));
console.log('errors:', errors.length ? errors.slice(0, 6) : 'none');
await browser.close();

