  // Absolute last resort: a plain oval always validates, but it is still a
  // fresh named circuit rather than a repeat of a previous inspiration.
  const pts = [];
  const cx = safeW / 2;
  const cy = safeH / 2;
  const radius = Math.min(safeW, safeH) * 0.4;
  for (let i = 0; i < 64; i++) {
    const a = (i / 64) * TAU;
    pts.push({ x: cx + Math.cos(a) * radius * 1.35, y: cy + Math.sin(a) * radius });
  }
  const named = trackNameFor(pts);
  return { points: pts, name: named.name, suffix: named.suffix, seed: named.seed, preview: fallback?.preview ?? analyzePreview(pts) };
}

input.newString:
  // Last resort: the first roll is still a unique, closed, non-intersecting
  // loop even when it missed a quality gate, so use it rather than an oval
  // that would look identical on every click.
  let pts = fallback?.points;
  if (!pts) {
    pts = [];
    const cx = safeW / 2;
    const cy = safeH / 2;
    const radius = Math.min(safeW, safeH) * 0.4;
    for (let i = 0; i < 64; i++) {
      const a = (i / 64) * TAU;
      pts.push({ x: cx + Math.cos(a) * radius * 1.35, y: cy + Math.sin(a) * radius });
    }
  }
  const preview = fallback?.preview ?? analyzePreview(pts);
  recentTrackPrints.push(trackFingerprint(preview.prepared));
  if (recentTrackPrints.length > 30) recentTrackPrints.shift();
  const named = trackNameFor(pts);
  return { points: pts, name: named.name, suffix: named.suffix, seed: named.seed, preview };
}

