cd /tmp/opencode && cat > final-smoke.mjs <<'EOF'
import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
launchOptions.executablePath = process.env.CHROME_PATH || '/opt/google/chrome/chrome';
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 1100, height: 700 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:3011/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && document.querySelector('#screen-menu.is-active'), null, { timeout: 60000 });
