/* ═══════════════════════════════════════════════════════════════════
   Endless inspiration tracks
   A superellipse base (oval → rounded rectangle) plus random radial
   harmonics gives a star-shaped loop, which can never self-intersect.
   Every roll is seeded from the clock so the well is infinite.
   ═══════════════════════════════════════════════════════════════════ */

const recentTrackPrints = [];

function trackFingerprint(prepared) {
  const stride = Math.max(1, Math.floor(prepared.length / 24));
  let print = '';
  for (let i = 0; i < prepared.length; i += stride) {
    print += `${Math.round(prepared[i].x / 10)},${Math.round(prepared[i].y / 10)};`;
  }
  return print;
}

function superellipseLoop(rng) {
  const exponent = 2 + rng() * 2.5;
  const ax = 0.82 + rng() * 0.36;
  const ay = 0.74 + rng() * 0.34;

  const freqs = [2, 3, 4, 5, 6, 7];
  for (let i = freqs.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [freqs[i], freqs[j]] = [freqs[j], freqs[i]];
  }
  const terms = [];
  let slope = 0;
  const harmonicCount = 2 + Math.floor(rng() * 3);
  for (let i = 0; i < harmonicCount; i++) {
    const freq = freqs[i];
    const maxAmp = Math.max(0.02, (1.45 - slope) / freq);
    const amp = Math.min((0.09 + rng() * 0.17) * (freq <= 3 ? 0.75 : 1), maxAmp);
    slope += amp * freq;
    terms.push({ freq, amp, phase: rng() * TAU });
  }

  const count = 64 + Math.floor(rng() * 24);
  const rot = rng() * TAU;
  const cr = Math.cos(rot);
  const sr = Math.sin(rot);
  const pts = [];
  for (let i = 0; i < count; i++) {
    const a = (i / count) * TAU;
    const c = Math.cos(a);
    const s = Math.sin(a);
    const base = Math.pow(
      Math.pow(Math.abs(c / ax), exponent) + Math.pow(Math.abs(s / ay), exponent),
      -1 / exponent
    );
    let r = base;
    for (const term of terms) r *= 1 + term.amp * Math.sin(term.freq * a + term.phase);
    r = Math.max(base * 0.55, r);
    const x = c * r;
    const y = s * r;
    pts.push({ x: x * cr - y * sr, y: x * sr + y * cr });
  }
  return pts;
}

